 * 全市（activeDistrict 为空）或未命中区时清空裁剪，恢复全市热力。
 */
applyDistrictClip() {
  const chart = this.chart
  if (!chart || !chart.getZr()) return
  const zr = chart.getZr()
  const layer = zr.painter && zr.painter.getLayer && zr.painter.getLayer(2)
  const dom = layer && layer.dom
  if (!dom) return
  const code = this.activeDistrict == null ? '' : String(this.activeDistrict)
  const feature = code && (suzhouGeo.features || []).find((f) => {
    const p = f.properties || {}
    return String(p.adcode) === code || String(p.name) === code
  })
  if (!feature || !feature.geometry) {
    dom.style.clipPath = ''
    return
  }
  const geom = feature.geometry
  const polygons = geom.type === 'MultiPolygon'
    ? geom.coordinates
    : geom.type === 'Polygon' ? [geom.coordinates] : []
  const parts = []
  polygons.forEach((rings) => {
    rings.forEach((ring) => {
      if (!ring || ring.length < 3) return
